python3 << 'EOF'
import json
import subprocess

# Test branch with long id
request = {
  "pipeline": {"steps": [
    {"op": "branch", "branches": [
      {"id": "1234567890123456789012345678901234567890123456789012345678901234567890", "when": "id > 5", "steps": []}
    ]}
  ]},
  "dataset": []
}

result = subprocess.run(["python", "etl_pipeline.py"],
                       input=json.dumps(request),
                       capture_output=True,
                       text=True)
print("Branch with long id:")
print(result.stdout)
print("---")

# Test branch with control character in when (should fail at SCHEMA_VALIDATION_FAILED, not BAD_EXPR)
request = {
  "pipeline": {"steps": [
    {"op": "branch", "branches": [
      {"when": "id\n> 5", "steps": []}
    ]}
  ]},
  "dataset": []
}

result = subprocess.run(["python", "etl_pipeline.py"],
                       input=json.dumps(request),
                       capture_output=True,
                       text=True)
print("Branch with control character in when:")
print(result.stdout)
print("---")

# Test merge.strategy validation
request = {
  "pipeline": {"steps": [
    {"op": "branch", "branches": [{"when": "id > 5", "steps": []}], "merge": {"strategy": "1234567890123456789012345678901234567890123456789012345678901234567890"}}
  ]},
  "dataset": []
}

result = subprocess.run(["python", "etl_pipeline.py"],
                       input=json.dumps(request),
                       capture_output=True,
                       text=True)
print("Merge with long strategy:")
print(result.stdout)
EOF

